create or replace function catalog.list_tenant_measurement_units(
  p_tenant_id uuid,
  p_keyword text default null,
  p_limit int default 50
)
returns table (
  id uuid,
  name text,
  is_active boolean
)
language plpgsql
security definer
set search_path = catalog, iam, pg_temp
as $$
declare
  v_keyword text := catalog._normalize_measurement_unit_name(p_keyword);
begin
  if auth.uid() is null then
    raise exception 'not authenticated';
  end if;

  if not iam.has_permission(p_tenant_id, 'catalog.product.manage_units') then
    raise exception 'permission denied: catalog.product.manage_units';
  end if;

  return query
  select tu.id, tu.name, tu.is_active
  from catalog.tenant_measurement_units tu
  where tu.tenant_id = p_tenant_id
    and (
      v_keyword is null
      or tu.name like '%' || v_keyword || '%'
    )
  order by tu.is_active desc, tu.name asc
  limit least(greatest(coalesce(p_limit, 50), 1), 100);
end;
$$;

create or replace function catalog.check_duplicate_measurement_unit_name(
  p_tenant_id uuid,
  p_name text
)
returns boolean
language plpgsql
security definer
set search_path = catalog, iam, pg_temp
as $$
declare
  v_unit_name text := catalog._normalize_measurement_unit_name(p_name);
begin
  if auth.uid() is null then
    raise exception 'not authenticated';
  end if;

  if not iam.has_permission(p_tenant_id, 'catalog.product.manage_units') then
    raise exception 'permission denied: catalog.product.manage_units';
  end if;

  if v_unit_name is null then
    raise exception 'validation_exception: Unit name must not be empty.';
  end if;

  return exists (
    select 1
    from catalog.tenant_measurement_units tu
    where tu.tenant_id = p_tenant_id
      and tu.name = v_unit_name
  );
end;
$$;

create or replace function catalog.set_product_base_unit(
  p_tenant_id uuid,
  p_product_id uuid,
  p_tenant_unit_id uuid default null,
  p_new_unit_name text default null
)
returns jsonb
language plpgsql
security definer
set search_path = catalog, iam, pg_temp
as $$
declare
  v_actor_id uuid;
  v_tenant_unit_id uuid;
  v_unit_name text;
  v_facts record;
  v_blockers jsonb;
  v_status catalog.product_readiness_status;
begin
  v_actor_id := auth.uid();
  if v_actor_id is null then
    raise exception 'not authenticated';
  end if;

  if not iam.has_permission(p_tenant_id, 'catalog.product.manage_units') then
    raise exception 'permission denied: catalog.product.manage_units';
  end if;

  if not exists (
    select 1
    from catalog.products p
    where p.id = p_product_id
      and p.tenant_id = p_tenant_id
      and p.deleted_at is null
  ) then
    raise exception 'product not found';
  end if;

  if catalog._product_has_active_base_unit(p_tenant_id, p_product_id) then
    raise exception 'validation_exception: Product already has a base unit; change base unit is out of scope.';
  end if;

  if (p_tenant_unit_id is null and catalog._normalize_measurement_unit_name(p_new_unit_name) is null)
     or (p_tenant_unit_id is not null and catalog._normalize_measurement_unit_name(p_new_unit_name) is not null) then
    raise exception 'validation_exception: Exactly one base unit selection is required.';
  end if;

  if p_tenant_unit_id is not null then
    select tu.id, tu.name
    into v_tenant_unit_id, v_unit_name
    from catalog.tenant_measurement_units tu
    where tu.id = p_tenant_unit_id
      and tu.tenant_id = p_tenant_id
      and tu.is_active = true;

    if v_tenant_unit_id is null then
      raise exception 'validation_exception: Measurement unit is inactive or not found.';
    end if;
  else
    v_unit_name := catalog._normalize_measurement_unit_name(p_new_unit_name);

    if length(v_unit_name) > 80 then
      raise exception 'validation_exception: Unit name is too long.';
    end if;

    select tu.id
    into v_tenant_unit_id
    from catalog.tenant_measurement_units tu
    where tu.tenant_id = p_tenant_id
      and tu.name = v_unit_name;

    if v_tenant_unit_id is not null then
      raise exception 'duplicate measurement unit "%"', v_unit_name;
    end if;

    insert into catalog.tenant_measurement_units (
      tenant_id,
      name,
      is_active,
      updated_at
    )
    values (
      p_tenant_id,
      v_unit_name,
      true,
      now()
    )
    returning id into v_tenant_unit_id;
  end if;

  insert into catalog.product_units (
    tenant_id,
    product_id,
    tenant_measurement_unit_id,
    unit_name,
    is_base_unit,
    conversion_rate_to_base,
    updated_at
  )
  values (
    p_tenant_id,
    p_product_id,
    v_tenant_unit_id,
    v_unit_name,
    true,
    1,
    now()
  );

  select *
  into v_facts
  from catalog._product_operational_facts(p_tenant_id, p_product_id);

  v_blockers := catalog._readiness_blockers_from_facts(
    v_facts.has_base_unit,
    v_facts.has_images,
    v_facts.has_stock,
    v_facts.has_base_price,
    v_facts.has_price_band,
    v_facts.has_required_custom_fields,
    v_facts.stock_mode,
    v_facts.base_price_mode
  );

  v_status := case
    when catalog._product_readiness_is_ready(
      v_facts.has_base_unit,
      v_facts.has_images,
      v_facts.has_stock,
      v_facts.has_base_price,
      v_facts.has_price_band,
      v_facts.has_required_custom_fields,
      v_facts.stock_mode,
      v_facts.base_price_mode
    ) then 'ready_to_sell'::catalog.product_readiness_status
    else 'incomplete'::catalog.product_readiness_status
  end;

  insert into catalog.product_readiness (product_id, tenant_id, status, blockers, updated_at)
  values (p_product_id, p_tenant_id, v_status, v_blockers, now())
  on conflict (product_id) do update set
    status = excluded.status,
    blockers = excluded.blockers,
    updated_at = now();

  insert into catalog.product_change_history (tenant_id, product_id, action, payload, actor_id)
  values (
    p_tenant_id,
    p_product_id,
    'set_product_base_unit',
    jsonb_build_object('tenant_measurement_unit_id', v_tenant_unit_id, 'unit_name', v_unit_name, 'readiness_status', v_status),
    v_actor_id
  );

  return jsonb_build_object(
    'product_id', p_product_id,
    'base_unit_name', v_unit_name,
    'readiness_status', v_status::text,
    'readiness_blockers', v_blockers
  );
end;
$$;

create or replace function catalog.add_product_conversion_unit(
  p_tenant_id uuid,
  p_product_id uuid,
  p_unit_name text,
  p_conversion_rate_to_base numeric
)
returns jsonb
language plpgsql
security definer
set search_path = catalog, iam, pg_temp
as $$
declare
  v_actor_id uuid;
  v_unit_name text := catalog._normalize_measurement_unit_name(p_unit_name);
  v_product_unit_id uuid;
begin
  v_actor_id := auth.uid();
  if v_actor_id is null then
    raise exception 'not authenticated';
  end if;

  if not iam.has_permission(p_tenant_id, 'catalog.product.manage_units') then
    raise exception 'permission denied: catalog.product.manage_units';
  end if;

  if not exists (
    select 1
    from catalog.products p
    where p.id = p_product_id
      and p.tenant_id = p_tenant_id
      and p.deleted_at is null
  ) then
    raise exception 'product not found';
  end if;

  perform catalog._ensure_product_has_base_unit(p_tenant_id, p_product_id);

  if v_unit_name is null then
    raise exception 'validation_exception: Unit name must not be empty.';
  end if;
  if length(v_unit_name) > 80 then
    raise exception 'validation_exception: Unit name is too long.';
  end if;
  if p_conversion_rate_to_base is null or p_conversion_rate_to_base <= 0 then
    raise exception 'validation_exception: Conversion rate must be greater than zero.';
  end if;

  if exists (
    select 1
    from catalog.product_units pu
    where pu.tenant_id = p_tenant_id
      and pu.product_id = p_product_id
      and pu.is_active = true
      and pu.unit_name = v_unit_name
  ) then
    raise exception 'duplicate product unit "%"', v_unit_name;
  end if;

  insert into catalog.product_units (
    tenant_id,
    product_id,
    unit_name,
    is_base_unit,
    conversion_rate_to_base,
    is_active,
    updated_at
  )
  values (
    p_tenant_id,
    p_product_id,
    v_unit_name,
    false,
    p_conversion_rate_to_base,
    true,
    now()
  )
  returning id into v_product_unit_id;

  insert into catalog.product_change_history (tenant_id, product_id, action, payload, actor_id)
  values (
    p_tenant_id,
    p_product_id,
    'add_product_conversion_unit',
    jsonb_build_object('product_unit_id', v_product_unit_id, 'unit_name', v_unit_name, 'conversion_rate_to_base', p_conversion_rate_to_base),
    v_actor_id
  );

  return jsonb_build_object(
    'product_id', p_product_id,
    'unit', catalog._product_unit_json(v_product_unit_id)
  );
end;
$$;

create or replace function catalog.reactivate_product_conversion_unit(
  p_tenant_id uuid,
  p_product_id uuid,
  p_product_unit_id uuid
)
returns jsonb
language plpgsql
security definer
set search_path = catalog, iam, pg_temp
as $$
declare
  v_actor_id uuid;
  v_unit record;
begin
  v_actor_id := auth.uid();
  if v_actor_id is null then
    raise exception 'not authenticated';
  end if;

  if not iam.has_permission(p_tenant_id, 'catalog.product.manage_units') then
    raise exception 'permission denied: catalog.product.manage_units';
  end if;

  select *
  into v_unit
  from catalog.product_units pu
  where pu.id = p_product_unit_id
    and pu.product_id = p_product_id
    and pu.tenant_id = p_tenant_id;

  if v_unit.id is null then
    raise exception 'product unit not found';
  end if;
  if v_unit.is_base_unit then
    raise exception 'validation_exception: Base unit cannot be reactivated here.';
  end if;
  if v_unit.conversion_rate_to_base <= 0 then
    raise exception 'validation_exception: Conversion rate must be greater than zero.';
  end if;
  if exists (
    select 1
    from catalog.product_units pu
    where pu.tenant_id = p_tenant_id
      and pu.product_id = p_product_id
      and pu.id <> p_product_unit_id
      and pu.is_active = true
      and pu.unit_name = v_unit.unit_name
  ) then
    raise exception 'duplicate product unit "%"', v_unit.unit_name;
  end if;

  update catalog.product_units
  set is_active = true,
      updated_at = now()
  where id = p_product_unit_id;

  insert into catalog.product_change_history (tenant_id, product_id, action, payload, actor_id)
  values (
    p_tenant_id,
    p_product_id,
    'reactivate_product_conversion_unit',
    jsonb_build_object('product_unit_id', p_product_unit_id, 'unit_name', v_unit.unit_name),
    v_actor_id
  );

  return jsonb_build_object(
    'product_id', p_product_id,
    'unit', catalog._product_unit_json(p_product_unit_id)
  );
end;
$$;

